declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");$u=$argv[1]??'admin';$p=$argv[2]??'';if(strlen($p)<12)exit("Usage: php bin/create_admin.php username 'StrongPassword12+'\n");$db=Database::pdo();$st=$db->prepare('INSERT INTO admin_users(username,password_hash,active,created_at,updated_at) VALUES(?,?,1,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),active=1,updated_at=UTC_TIMESTAMP()');$st->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);echo "Admin user ready: {$u}\n";
